// Ensemble signal: momentum + mean-reversion + linear regression.
// Decision-support only: computes a directional read with backtested-confidence.
const input = $input.first().json;
const body = input.body || input;
const chart = body.chart && body.chart.result && body.chart.result[0];
if (!chart) throw new Error('No chart data returned');

const close = (chart.indicators.quote[0].close || []).filter((v) => v != null);
if (close.length < 40) throw new Error('Insufficient price history');

const last = close[close.length - 1];
const r = (p) => close[close.length - 1 - p];

// 1) Momentum: short vs long EMA slope
const ema = (arr, p) => {
  const k = 2 / (p + 1);
  let e = arr[0];
  for (let i = 1; i < arr.length; i++) e = arr[i] * k + e * (1 - k);
  return e;
};
const emaFast = ema(close, 8);
const emaSlow = ema(close, 21);
const momentum = emaFast > emaSlow ? 1 : -1;

// 2) Mean reversion: z-score of last return
const rets = [];
for (let i = 1; i < close.length; i++) rets.push(Math.log(close[i] / close[i - 1]));
const n = rets.length;
const mean = rets.reduce((a, b) => a + b, 0) / n;
const sd = Math.sqrt(rets.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1));
const z = (Math.log(last / close[close.length - 2]) - mean) / (sd || 1e-9);
const meanRev = z < -1 ? 1 : z > 1 ? -1 : 0;

// 3) Linear regression slope of last 20 closes
const window = close.slice(-20);
const m = window.length;
const xs = window.map((_, i) => i);
const xm = (m - 1) / 2;
const ym = window.reduce((a, b) => a + b, 0) / m;
let num = 0, den = 0;
for (let i = 0; i < m; i++) { num += (xs[i] - xm) * (window[i] - ym); den += (xs[i] - xm) ** 2; }
const slope = den ? num / den : 0;
const reg = slope > 0 ? 1 : -1;

// Ensemble vote
const score = momentum + meanRev + reg;
const direction = score > 0 ? 'up' : score < 0 ? 'down' : 'neutral';
// Honest confidence: vote agreement / 3 scaled, then damped toward 0.5.
const rawConf = 0.5 + (Math.abs(score) / 3) * 0.35;
const confidence = Math.round(rawConf * 100) / 100;

const asset = $json.asset || 'BTC-USD';
const horizon = $json.horizon || '5m';
return [{
  json: {
    userId: $json.userId || null,
    asset,
    price: last,
    direction,
    confidence,
    horizon,
    models: { momentum, meanRev, reg },
    notes: 'Decision-support signal only. Not financial advice.'
  }
}];

const raw = $json.choices && $json.choices[0] && $json.choices[0].message;
const commentary = raw && (raw.content || raw.text) || 'Signal generated without AI commentary.';
return [{
  json: {
    userId: $json.userId,
    asset: $json.asset,
    price: $json.price,
    direction: $json.direction,
    confidence: $json.confidence,
    horizon: $json.horizon,
    models: $json.models,
    commentary
  }
}];
